// Discover the eufy app's request/response crypto classes at runtime.
//
// The transport is pure-Kotlin (korlibs.crypto), so javax.crypto and native
// TLS hooks never see plaintext. Attach this after the app has reached the
// device screen, then trigger the firmware check: any method whose name looks
// like crypto is listed with its signature so the payload hook can target it.
Java.perform(function () {
    var interesting = /esiotkit|EncryptKeyFactory|MegaFieldCrypto|CryptoRequest|KeySaver/i;
    var seen = {};

    function className(c) {
        try {
            return c.getName();
        } catch (e) {
            return null;
        }
    }

    function dumpClass(name) {
        if (seen[name]) return;
        seen[name] = true;
        send({ kind: "class", name: name });
        try {
            var c = Java.use(name);
            var methods = c.class.getDeclaredMethods();
            for (var i = 0; i < methods.length; i++) {
                var m = methods[i];
                send({
                    kind: "method",
                    cls: name,
                    name: m.getName(),
                    sig: String(m),
                });
            }
        } catch (e) {
            send({ kind: "error", name: name, error: String(e) });
        }
    }

    function scan() {
        Java.enumerateLoadedClasses({
            onMatch: function (name) {
                if (interesting.test(name)) dumpClass(name);
            },
            onComplete: function () {
                send({ kind: "scan-done", total: Object.keys(seen).length });
            },
        });
    }

    scan();

    // Classes only exist after the relevant screen loads, so rescan on demand.
    rpc.exports.scan = function () {
        scan();
        return Object.keys(seen).length;
    };
});

