// Print eufy request/response plaintext before the app-layer crypto runs.
//
// The transport encrypts JSON with korlibs.crypto under an ECDH session key, so
// the ciphertext is all that exists on the wire and javax.crypto never sees it.
// Every payload is still a Kotlin object serialised to a JSON string first, so
// intercepting kotlinx.serialization prints the plaintext on both directions
// without knowing any eufy-specific class name.
//
// OkHttp is hooked only to label each payload with the URL it belongs to.
Java.perform(function () {
    var MAX = 4000;

    function trim(s) {
        s = String(s);
        return s.length > MAX ? s.substring(0, MAX) + "...[" + s.length + " chars]" : s;
    }

    function hookJson() {
        ["kotlinx.serialization.json.Json", "kotlinx.serialization.json.JsonImpl"].forEach(function (name) {
            try {
                var Json = Java.use(name);
                ["encodeToString", "decodeFromString"].forEach(function (fn) {
                    try {
                        var overloads = Json[fn].overloads;
                        overloads.forEach(function (ov) {
                            var argc = ov.argumentTypes.length;
                            ov.implementation = function () {
                                var out = ov.apply(this, arguments);
                                var payload = fn === "encodeToString" ? out : arguments[argc - 1];
                                if (payload !== null && payload !== undefined) {
                                    var text = trim(payload);
                                    if (/rom|firmware|version|device_sn|deviceSn|ota/i.test(text)) {
                                        send({ kind: "payload", dir: fn === "encodeToString" ? "REQ" : "RESP", data: text });
                                    }
                                }
                                return out;
                            };
                        });
                        send({ kind: "hooked", target: name + "." + fn, overloads: overloads.length });
                    } catch (e) {
                        send({ kind: "skip", target: name + "." + fn, error: String(e) });
                    }
                });
            } catch (e) {
                send({ kind: "skip", target: name, error: String(e) });
            }
        });
    }

    function hookHttp() {
        try {
            var RealCall = Java.use("okhttp3.RealCall");
            RealCall.execute.implementation = function () {
                try {
                    var r = this.request();
                    send({ kind: "http", method: String(r.method()), url: String(r.url().toString()) });
                } catch (e) {}
                return this.execute();
            };
        } catch (e) {
            send({ kind: "skip", target: "okhttp3.RealCall", error: String(e) });
        }
    }

    hookJson();
    hookHttp();
    send({ kind: "ready" });
});

